// Toutes les informations pour modifier
// les valeurs du shader sont ci-dessous.
void mainImage(out vec4 couleurSortie, vec2 coordonneesPixel) {
    vec3 resolution = iResolution;

    // Matrice d'orientation de la caméra : modifier les valeurs pour incliner ou pivoter la vue
    mat3 matriceOrientation = mat3(
        3.0,  1.0,  0.7,
        1.0, -3.0,  6.0,
       -0.88, 2.0,  4.0
    ) * 0.1;

    // Calcul des coordonnées UV et champ de vision (FOV) :
    // - Ajuster 3.0 pour modifier le zoom global
    // - Ajuster 2.0 (valeur Z de directionRayon) pour élargir/réduire le FOV
    vec2 uv = (coordonneesPixel * 3.0 - resolution.xy) / resolution.y;
    vec3 directionRayon = vec3(uv, 2.0) * matriceOrientation;

    couleurSortie = vec4(0.0);

    // Origine du rayon : modifier -6.0 pour avancer/reculer la caméra sur l'axe Y
    vec3 positionRayon;
    positionRayon.y = -6.0;

    // Nombre d'étapes de raymarching : augmenter 80 pour plus de précision volumétrique
    for (int etape = 0; etape < 80; etape++) {
        // Seuil de saturation alpha pour stopper la boucle plus tôt
        if (couleurSortie.a >= 8.0) {
            break;
        }

        vec3 positionCourante = positionRayon;
        float distanceOrigine = length(positionCourante);

        // Facteurs de torsion log-polaire :
        // - Ajuster 0.45 pour modifier l'intensité de la spirale
        // - Ajuster les décalages vec4(0.0, 11.0, 33.0, 0.0) pour changer l'orientation des bras
        vec4 anglesRotation = log(distanceOrigine) * 0.45 - vec4(0.0, 11.0, 33.0, 0.0);
        mat2 matriceRotation = mat2(
            cos(anglesRotation.x), cos(anglesRotation.y),
            cos(anglesRotation.z), cos(anglesRotation.w)
        );
        positionCourante.xz *= matriceRotation;

        // Coordonnées de bruit log-polaire :
        // - Ajuster 0.1 et -0.02 pour modifier la vitesse et le sens d'écoulement
        // - Ajuster 8.0 pour changer le nombre de répétitions du motif
        vec3 coordonneesBruit = vec3(
            fract(log(distanceOrigine) * 0.1 - iTime * 0.02) * 8.0,
            exp(-positionCourante.y / distanceOrigine),
            atan(positionCourante.x, positionCourante.z)
        );

        // Seuil de densité de base : ajuster 0.3 pour rendre la nébuleuse plus fine ou plus dense
        float densiteEspace = coordonneesBruit.y - 0.3;

        // Boucle d'octaves FBM (bruit procédural) :
        // - Ajuster 4.0 (début) et 500.0 (fin) pour la plage de fréquences des détails
        // - Ajuster 0.8 pour l'amplitude des turbulences (lisse vs rugueux)
        for (float echelle = 4.0; echelle < 500.0; echelle += echelle) {
            vec3 ondeSinus = sin(coordonneesBruit.yzx * echelle);
            vec3 ondeCosinus = cos(coordonneesBruit * echelle);
            densiteEspace -= abs(dot(ondeSinus, ondeCosinus)) * 0.8 / echelle;
        }

        densiteEspace = max(densiteEspace, 0.0);

        // Palette de couleurs et vitesse de défilement :
        // - Ajuster 0.02 et 0.003 pour l'intensité lumineuse globale
        // - Ajuster vec4(6.0, 1.0, 2.0, 0.0) pour décaler les teintes (RGB)
        vec4 couleurTeinte = 0.02 + 0.003 * cos(distanceOrigine - iTime + vec4(6.0, 1.0, 2.0, 0.0));

        // Gain d'accumulation lumineuse volumétrique : ajuster 1024.0 et 0.4 pour le contraste
        couleurSortie += min(densiteEspace * 1024.0, 0.4 - densiteEspace) * couleurTeinte;

        // Pas d'avancement du rayon : ajuster 0.2 pour équilibrer précision visuelle et performances
        positionRayon += directionRayon * max(densiteEspace, 0.001) * distanceOrigine * 0.2;
    }

    // Post-traitement (tonemapping, compression de la courbe de couleur et niveau de noir)
    couleurSortie -= 0.5;
    couleurSortie /= couleurSortie + 0.2 + 0.15 / couleurSortie;
}
